1024: /**
1025:  * @brief Test a WiFi connection without permanently changing stored credentials.
1026:  */
1027: bool WifiManager::testConnection(const char* ssid, const char* pass, std::string& ipOut) {
1028:     ESP_LOGI(TAG, "WIFI_TEST: Starting connection test...");
1029:     const char* realPass = pass;
1030:     if (pass != nullptr && strlen(pass) == 0) {
1031:         ESP_LOGI(TAG, "WIFI_TEST: Using stored credentials for test.");
1032:         realPass = _wifiPass;
1033:     }
1034: 
1035:     if (WiFi.status() == WL_CONNECTED && strcmp(WiFi.SSID().c_str(), ssid) == 0 && strcmp(realPass, _wifiPass) == 0) {
1036:         ipOut = WiFi.localIP().toString().c_str();
1037:         ESP_LOGI(TAG, "WIFI_TEST: Already connected to this network. IP: %s", ipOut.c_str());
1038:         return true;
1039:     }
1040: 
1041:     WiFi.disconnect(true);
1042:     // HARDWARE SETTLING: ESP32 WiFi stack requires ~200ms between disconnect()
1043:     // and subsequent begin() to release the radio hardware. Without this delay,
1044:     // WiFi.begin() can silently fail or connect to the wrong BSSID. Verified
1045:     // empirically on ESP32-S3; the ESP-IDF WiFi driver does not guarantee
1046:     // immediate readiness after disconnect(true).
1047:     delay(200);
1048: 
1049:     connectStation(ssid, realPass);
1050:     
1051:     int retries = 0;
1052:     while (WiFi.status() != WL_CONNECTED && retries < 20) {
1053:         // BLOCKING POLL: testConnection() is intentionally synchronous — it
1054:         // blocks the calling context (web handler) until the connection result
1055:         // is known. 500ms × 20 iterations = 10s max wait, matching typical
1056:         // WPA2 association + DHCP time.
1057:         delay(500);
1058:         retries++;
1059:     }
1060: 
1061:     if (WiFi.status() == WL_CONNECTED) {
1062:         ipOut = WiFi.localIP().toString().c_str();
1063:         ESP_LOGI(TAG, "WIFI_TEST: Success! IP: %s", ipOut.c_str());
1064:         return true;
1065:     } else {
1066:         ESP_LOGW(TAG, "WIFI_TEST: Failed. Reconnecting to primary credentials.");
1067:         if (strlen(_wifiSsid) > 0) {
1068:             WiFi.disconnect(true);
1069:             // HARDWARE SETTLING: Short delay after disconnect() before
1070:             // reconnecting to the primary network. 100ms is sufficient here
1071:             // because the radio is transitioning to a known-good configuration
1072:             // (the stored STA credentials) rather than a new network.
1073:             delay(100);
1074:             connectStation(_wifiSsid, _wifiPass);
1075:         }
1076:         return false;
1077:     }
1078: }
